package com.gamehubstore.review_mscv.repositories; import com.gamehubstore.review_mscv.models.Review; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import java.util.*;
public interface ReviewRepository extends JpaRepository<Review,Long> { List<Review> findByProductIdAndActiveTrue(Long productId); List<Review> findByUserId(Long userId); boolean existsByUserIdAndOrderIdAndProductId(Long userId,Long orderId,Long productId); List<Review> findByEstadoIgnoreCase(String estado); @Query("SELECT r.productId, AVG(r.rating), COUNT(r) FROM Review r WHERE r.active = true AND r.productId IN :ids GROUP BY r.productId") List<Object[]> resumenPorProductos(@Param("ids") List<Long> ids); }
